Scheme kc__5 := Elimination for Corelib.Init.Logic.ex Sort Prop.

(* [comment removed for export] *)
Lemma svc_mid : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' xs7 xs8 v0 : word)
    (sv dst src spa lo shi ff fp : Z) (bs : list byte) (rest : list cell) (LF : list fframe) (m m2 : mem) (j24 v16 junk1 junk2 junk : list byte),
  rw_cells bsegs m2 (bv_unsigned sp + -128) [C8 v0; CB 24 j24; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells bsegs m2 (bv_unsigned sp + -144) [CB 16 v16] ->
  rw_cells bsegs m2 ff [CB 24 junk1; C8 (Z_to_bv 64 spa); CB 24 junk2; C8 (Z_to_bv 64 fp)] ->
  SHAD m2 ff (poison_bytes 8 0) ->
  rw_cells bsegs m2 fp [C1 (b8 1)] ->
  stk bsegs m2 lo (bv_unsigned sp + -144) -> mem_inv bsegs m2 ->
  as_RFS H ((0, ff, fp) :: LF) m2 -> ACONST m2 -> stack0 m2 lo shi ->
  munch (svc_W lo sp dst (zlength bs) ff fp) m m2 -> wmono bsegs m m2 ->
  (spa = bv_unsigned sp + -128 \/ spa = bv_unsigned sp + -144) ->
  lo + SVC_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp <= sv -> sv + 16 <= shi -> sv mod 8 = 0 -> bv_unsigned sp + 64 <= shi ->
  bv_unsigned ra mod 2 = 0 ->
  (* [comment removed for export] *)
  rw_cells bsegs m2 sv (C8 (wz src) :: C8 (wz (zlength bs)) :: rest) -> bytes_at bsegs m2 src bs -> rw_cells bsegs m2 dst [CB (length bs) junk] ->
  (src + zlength bs <= dst \/ dst + zlength bs <= src) ->
  (dst + zlength bs <= sv \/ sv + Z.of_nat (cells_size (C8 (wz src) :: C8 (wz (zlength bs)) :: rest)) <= dst) ->
  (dst + zlength bs <= lo \/ bv_unsigned sp <= dst) -> (src + zlength bs <= lo \/ bv_unsigned sp <= src) ->
  as_RFS H LF m -> zlength bs <= 2^40 -> svc_obj LF m2 bs src -> svc_obj LF m2 bs dst ->
  evt bsegs (svc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc sv dst src bs rest LF lo shi m)
    (MS (mkR (Z_to_bv 64 0xba7e0) (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) (Z_to_bv 64 dst) (Z_to_bv 64 0) (Z_to_bv 64 sv) (Z_to_bv 64 (zlength bs)) xs7
             xs8 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3' t4' t5' t6')
